package com.agacostays.billing.consumer;import com.agacostays.billing.service.BillingService;import com.fasterxml.jackson.databind.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;@Component public class PaymentSuccessEventConsumer{private final BillingService s;private final ObjectMapper m;public PaymentSuccessEventConsumer(BillingService s,ObjectMapper m){this.s=s;this.m=m;}@KafkaListener(topics="payment.success",groupId="billing-service-payment")public void consume(String msg){try{JsonNode n=m.readTree(msg);if(n.hasNonNull("billId"))s.markPaidFromEvent(n.get("billId").asLong());}catch(Exception ignored){}}}
